"""
Pydantic Schemas for AI-Assisted Reconciliation (Phase 9).
Defines structured LLM input/output specifications, validation contracts,
safety constraints, and API request/response models.
"""
import uuid
from datetime import date, datetime
from decimal import Decimal
from typing import List, Optional, Dict, Any
from pydantic import BaseModel, Field, field_validator


class CandidateProposal(BaseModel):
    """Structured proposal generated by the LLM for a single candidate pairing."""
    candidate_ledger_entry_id: str = Field(
        ...,
        description="The unique identifier (ID) of the ledger entry proposed as a match.",
    )
    confidence_score: float = Field(
        ...,
        ge=0.0,
        le=1.0,
        description="Model confidence score between 0.0 and 1.0.",
    )
    reasoning_summary: str = Field(
        ...,
        min_length=5,
        max_length=1000,
        description="Plain-English explanation of why this ledger entry matches the bank transaction.",
    )
    matching_signals: List[str] = Field(
        default_factory=list,
        description="List of detected financial and contextual signals (e.g., merchant similarity, invoice match).",
    )
    potential_concerns: List[str] = Field(
        default_factory=list,
        description="List of potential discrepancies, anomalies, or risks (e.g. date lag, variance).",
    )

    @field_validator("confidence_score")
    @classmethod
    def round_confidence(cls, v: float) -> float:
        return round(float(v), 4)


class LLMRankingResponse(BaseModel):
    """Top-level structured JSON output contract required from OpenAI."""
    ranked_candidates: List[CandidateProposal] = Field(
        default_factory=list,
        description="Ordered list of candidate proposals, ranked from most to least likely match.",
    )
    no_match_found: bool = Field(
        default=False,
        description="True if none of the provided ledger candidates represents a legitimate match.",
    )
    analysis_notes: str = Field(
        default="",
        description="High-level contextual reasoning about the transaction pool.",
    )


class AIReconciliationRunRequest(BaseModel):
    """API request payload to execute an AI-assisted reconciliation run."""
    bank_account_id: Optional[uuid.UUID] = None
    start_date: Optional[date] = None
    end_date: Optional[date] = None
    confidence_threshold: Optional[float] = Field(default=None, ge=0.5, le=1.0)
    model_override: Optional[str] = None
    date_window_days: Optional[int] = Field(default=7, ge=0, le=60)
    fee_tolerance: Optional[str] = Field(default="0.00")
    allow_fee_adjustment: Optional[bool] = Field(default=False)


class AIProposalDetail(BaseModel):
    """Detailed item representing an evaluated AI match proposal."""
    bank_transaction_id: str
    bank_booking_date: date
    bank_description: str
    bank_amount: str
    bank_currency: str
    bank_direction: str

    ledger_entry_id: Optional[str] = None
    ledger_posting_date: Optional[date] = None
    ledger_description: Optional[str] = None
    ledger_amount: Optional[str] = None
    ledger_account_code: Optional[str] = None

    confidence_score: float
    decision_status: str  # MATCHED, NEEDS_REVIEW, UNMATCHED, REJECTED
    rule_name: str
    reasoning_summary: str
    matching_signals: List[str]
    potential_concerns: List[str]
    deterministic_rule_passed: bool
    failure_reason: Optional[str] = None


class AIReconciliationRunResponse(BaseModel):
    """API response summarizing an AI-assisted reconciliation run."""
    run_id: uuid.UUID
    organization_id: uuid.UUID
    total_bank_unmatched_analyzed: int
    ai_proposals_generated: int
    validated_matches: int
    needs_review_count: int
    rejected_by_rules_count: int
    unmatched_remaining: int
    execution_duration_ms: int
    model_used: str
    prompt_version: str
    proposals: List[AIProposalDetail]
